import type { SeedData } from '@shared/types'
import seedJson from '@data/havel.character.json'

/**
 * The app's seed: generated by `npm run seed` from the saved D&D Beyond payload (see scripts/import-ddb.ts).
 * Only `state/session.ts` imports this. Its structure is verified at startup by `createCatalog()` and in
 * scripts/normalize.test.ts, so the cast below is checked rather than trusted.
 */
export const seed = seedJson as unknown as SeedData
